        <el-table-column label="附件名" prop="fileName" min-width="120" show-overflow-tooltip />
        <el-table-column label="委托备注" prop="wtRemarks" min-width="120" show-overflow-tooltip />
        <el-table-column align="center" fixed="right" label="操作" width="160">
          <template #default="scope">
            <el-button link type="primary" @click="openDetail(scope.row.id)">查看</el-button>
            <el-button link type="primary" @click="openForm('update', scope.row.id)">编辑</el-button>
            <el-button link type="danger" @click="handleDelete(scope.row.id)">删除</el-button>
          </template>
        </el-table-column>
    </el-table>
    <Pagination v-model:limit="queryParams.pageSize" v-model:page="queryParams.pageNo" :total="total" @pagination="getList" />
  </ContentWrap>

  <BoxunCommissionOrderForm ref="formRef" @success="getList" />
  <BoxunCommissionOrderDetail ref="detailRef" />
</template>

<script setup lang="ts">
import { onBeforeUnmount } from 'vue'
import { dateFormatter } from '@/utils/formatTime'
import request from '@/config/axios'
import download from '@/utils/download'
import * as BoxunCommissionOrderApi from './BoxunCommissionOrderApi'
import BoxunCommissionOrderForm from './BoxunCommissionOrderForm.vue'
import BoxunCommissionOrderDetail from './BoxunCommissionOrderDetail.vue'
import { currentProjectId, loadProjects } from '@/features/project/projectContext'

type BoxunCommissionOrderRow = Awaited<ReturnType<typeof BoxunCommissionOrderApi.getBoxunCommissionOrderPage>>['list'][number]
type EntityId = string | number

defineOptions({ name: 'BoxunCommissionOrder' })

const message = useMessage()
const { t } = useI18n()
const loading = ref(false)
const total = ref(0)
const rows = ref<BoxunCommissionOrderRow[]>([])
const queryFormRef = ref()
const queryParams = reactive({
  pageNo: 1,
  pageSize: 10,
  projectId: '',
  projectName: '',
  projectNameWithLou: '',
  witnessUnit: '',
  constructionOrganization: '',
  clientAndContactNumber: '',
  witnessAndContactNumber: '',
  addressOfTheInspectionUnit: '',
  reportNumber: '',
  materialName: '',
  normativeEncoding: '',
  fileName: '',
  wtRemarks: ''
})



const getList = async () => {
  loading.value = true
  try {
    await loadProjects()
    queryParams.projectId = currentProjectId.value
    const data = await BoxunCommissionOrderApi.getBoxunCommissionOrderPage(queryParams)
    rows.value = data.list
    total.value = Number(data.total)
  } finally {
    loading.value = false
  }
}

const handleQuery = () => {
  queryParams.pageNo = 1
  getList()
}

const resetQuery = () => {

  queryFormRef.value?.resetFields()

  handleQuery()
}

const formRef = ref()
const openForm = (type: 'create' | 'update', id?: EntityId) => {
  formRef.value?.open(type, id, type === 'create' ? undefined : undefined)
}


const detailRef = ref()
const openDetail = (id: EntityId) => {
  detailRef.value?.open(id)
}



const handleDelete = async (id?: EntityId) => {
  if (id === undefined) return
  await message.delConfirm()
  await BoxunCommissionOrderApi.deleteBoxunCommissionOrder(id)
  message.success(t('common.delSuccess'))
  await getList()
}

const checkedIds = ref<EntityId[]>([])
const handleSelectionChange = (rows: BoxunCommissionOrderRow[]) => {
  checkedIds.value = rows.map((row) => row.id).filter((id): id is EntityId => id !== undefined)
}

const handleDeleteBatch = async () => {
  await message.delConfirm()
  await BoxunCommissionOrderApi.deleteBoxunCommissionOrderList(checkedIds.value)
  message.success(t('common.delSuccess'))
  checkedIds.value = []
  await getList()
}
const exportLoading = ref(false)
const handleExport = async () => {
  await message.exportConfirm()
  exportLoading.value = true
  try {
    const data = await request.download({ url: '/boxun/commission-order/export-excel', params: queryParams })
    download.excel(data, 'boxunCommissionOrder.xls')
  } finally {
    exportLoading.value = false
  }
}

onMounted(getList)

const handleProjectChanged = () => {
  queryParams.pageNo = 1
  void getList()
}

onMounted(() => {
  window.addEventListener('boxun:project-changed', handleProjectChanged)
})

onBeforeUnmount(() => {
  window.removeEventListener('boxun:project-changed', handleProjectChanged)
})
</script>
